SELECT 
FROM pos_member m
LEFT JOIN pos_member_level l ON l.id = m.level_id
LEFT JOIN store_info st ON st.id = m.store_id


        (m.name LIKE CONCAT('%', #{q.keyword}, '%') OR m.phone LIKE CONCAT('%', #{q.keyword}, '%')
         OR m.member_code LIKE CONCAT('%', #{q.keyword}, '%'))

    AND m.level_id = #{q.levelId}
    AND m.store_id = #{q.storeId}
    AND m.status = #{q.status}

ORDER BY m.id DESC

